    return switch (v) {
      'zero' => Rect.zero,
      'largest' => Rect.largest,
      _ => fuseBad('Rect', v),
    };
  }
  final m = v as Map;
  switch (m[r'$']) {
    case 'fromLTRB':
      return Rect.fromLTRB(fuseReq(decDouble(m['left']), 'Rect.fromLTRB', 'left'), fuseReq(decDouble(m['top']), 'Rect.fromLTRB', 'top'), fuseReq(decDouble(m['right']), 'Rect.fromLTRB', 'right'), fuseReq(decDouble(m['bottom']), 'Rect.fromLTRB', 'bottom'));
    case 'fromLTWH':
      return Rect.fromLTWH(fuseReq(decDouble(m['left']), 'Rect.fromLTWH', 'left'), fuseReq(decDouble(m['top']), 'Rect.fromLTWH', 'top'), fuseReq(decDouble(m['width']), 'Rect.fromLTWH', 'width'), fuseReq(decDouble(m['height']), 'Rect.fromLTWH', 'height'));
    case 'fromCircle':
      return Rect.fromCircle(center: fuseReq(decOffset(m['center']), 'Rect.fromCircle', 'center'), radius: fuseReq(decDouble(m['radius']), 'Rect.fromCircle', 'radius'));
    case 'fromCenter':
      return Rect.fromCenter(center: fuseReq(decOffset(m['center']), 'Rect.fromCenter', 'center'), width: fuseReq(decDouble(m['width']), 'Rect.fromCenter', 'width'), height: fuseReq(decDouble(m['height']), 'Rect.fromCenter', 'height'));
    case 'fromPoints':
      return Rect.fromPoints(fuseReq(decOffset(m['a']), 'Rect.fromPoints', 'a'), fuseReq(decOffset(m['b']), 'Rect.fromPoints', 'b'));
  }
  return fuseBad('Rect', v);
}

Size? decSize(Object? v) {
  if (v == null) return null;
  if (v is String) {
    return switch (v) {
      'zero' => Size.zero,
      'infinite' => Size.infinite,
      _ => fuseBad('Size', v),
    };
  }
  final m = v as Map;
  switch (m[r'$']) {
    case null:
      return Size(fuseReq(decDouble(m['width']), 'Size', 'width'), fuseReq(decDouble(m['height']), 'Size', 'height'));
    case 'copy':
      return Size.copy(fuseReq(decSize(m['source']), 'Size.copy', 'source'));
    case 'square':
      return Size.square(fuseReq(decDouble(m['dimension']), 'Size.square', 'dimension'));
    case 'fromWidth':
      return Size.fromWidth(fuseReq(decDouble(m['width']), 'Size.fromWidth', 'width'));
    case 'fromHeight':
      return Size.fromHeight(fuseReq(decDouble(m['height']), 'Size.fromHeight', 'height'));
    case 'fromRadius':
      return Size.fromRadius(fuseReq(decDouble(m['radius']), 'Size.fromRadius', 'radius'));
  }
  return fuseBad('Size', v);
}

